#define N 100005

int arr[N];
int temp[N];

long merge(int* arr, int l, int m, int r) {
    long ans = 0;
    for(int i = l, j = m + 1, sum = 0; j <= r; j++) {
        while(i <= m && arr[i] <= arr[j]) {
            sum += arr[i++];
        }
        ans += sum;
    }

    int i = l, j = m + 1, k = l;
    while(i <= m && j<= r) {
        if(arr[i] <= arr[j]) {
            temp[k] = arr[i++];
        } else {
            temp[k] = arr[j++];
