        k++;
    }

    while(i <= m) {
        temp[k++] = arr[i++];
    }

    while(j <= r) {
        temp[k++] = arr[j++];
    }

    while(l <= r) {
        arr[l] = temp[l];
        l++;
    }

    return ans;
}

long merge_sort(int* arr, int l, int r) {
    if(l == r) return 0;

    int mid = l + ((r - l) >> 1);

    long left = merge_sort(arr, l, mid);
    long right = merge_sort(arr, mid + 1, r);

    long cross = merge(arr, l, mid, r);

    return left + right + cross;
