```c++
class Solution {
public:
    vector<vector<int>> permute(vector<int>& nums) {
        f(nums, 0);
        return ans;
    }

    void f(vector<int>& nums, int i) {
        if(i == nums.size()) {
            ans.push_back(nums);
        } else {
            for(int j = i; j < nums.size(); j++) {
                swap(nums[i], nums[j]);
                f(nums, i + 1);
                swap(nums[i], nums[j]);
            }
        }

    }

private:
    vector<vector<int>> ans;
};
