用递归函数逆序栈

```c++
#define N 1001
int top = -1;
int stack[N];

void reverse(void) {
    if(top == -1) {
        return;
    }

    int element = bottom_out();
    reverse();

    stack[++top] = element;
}

int bottom_out(void) {
    int cur = stack[top--];
    if(top == -1) {
        return cur;
    }

    int ans = bottom_out();
    stack[++top] = cur;

    return ans;
}
```

只使用递归给栈排序，从栈顶到栈底，从小到大

```c++
#define N 1005
int top = -1;
int stack[N];


void stack_sort(void){
    int depth = top;

    int max_val, locate;
    for(int i = depth; i >= 0; i--) {
        max_val = INT_MIN;
        locate = -1;

        val_to_bottom(i, &max_val, &locate);
    }
}

int val_to_bottom(int depth, int* max_val, int* locate) {
    int cur = stack[top--];

    if(cur > *max_val) {
        *max_val = cur;
        *locate = depth;
    }

    if(depth == 0) {
        stack[++top] = *max_val;
        return cur;
    }

    int val = val_to_bottom(depth - 1, max_val, locate);
    if(*locate == depth) {
        stack[++top] = val;
    } else {
        stack[++top] = cur;
    }

    return val;
}
```

含有嵌套的表达式求值
[测试链接](https://www.nowcoder.com/practice/c215ba61c8b1443b996351df929dc4d4)

```c++
#include <vector>
class Solution {
  public:
    int solve(string s) {
        where = 0;
        return f(s, 0);
    }

    int f(string& str, int i) {
        int val = 0;
        vector<int> number;
        vector<char> ops;
        while (i < str.size() && str[i] != ')') {
            if (str[i] >= '0' && str[i] <= '9') {
                val = val * 10 + str[i++] - '0';
            } else if (str[i] != '(') {
                push(number, ops, val, str[i++]);
                val = 0;
            } else {
                val = f(str, i + 1);
                i = where;
            }
        }

        push(number, ops, val, '+');
        where = i + 1;
        return compute(number, ops);
    }

    void push(vector<int>& digital, vector<char>& ops, int cur, int op) {
        int n = digital.size();
        if (n == 0 || ops[n - 1] == '+' || ops[n - 1] == '-') {
            digital.push_back(cur);
            ops.push_back(op);
        } else {
            char top_op = ops[n - 1];
            digital[n - 1] *= cur;
            ops[n - 1] = op;
        }
    }

    int compute(vector<int>& number, vector<char>& ops) {
		int n = number.size();
		int ans = number[0];
		for (int i = 1; i < n; i++) {
			ans += ops[i - 1] == '+' ? number[i] : -number[i];
		}
		return ans;
    }

private:
    int where;
};
```

