```c++
class Solution {
public:
    string decodeString(string s) {
        int where = 0;

        return f(s, 0, where);
    }

    string f(string& str, int i, int& where) {
        int cnt = 0;
        stringstream ss;
        string s;
        while (i < str.size() && str[i] != ']') {
            if(str[i] >= 'a' && str[i] <= 'z') {
                ss << str[i++];
            } else if(str[i] >= '0' && str[i] <= '9') {
                cnt = cnt * 10 + str[i++] - '0';
            } else {
                s = f(str, i + 1, where);
                stringstream temp;
                for(int i = 0; i < cnt; i++) {
                    temp << s;
                }

                ss << temp.str();

                cnt = 0;
                i = where;
            }
        }

        where = i + 1;
        return ss.str();
    }
};
```

含有嵌套的分子式求原子数量
[测试链接](https://leetcode.cn/problems/number-of-atoms/)

```c++
class Solution {
public:
    string countOfAtoms(string formula) {
        int where = 0;
        map<string, int> atoms_cnt = f(formula, 0, where);
        stringstream ss;
        for (pair<const string, int>& ky : atoms_cnt) {
            ss << ky.first;
            if (ky.second > 1) {
                ss << ky.second;
            }
        }

        return ss.str();
    }

    map<string, int> f(string& s, int i, int& where) {
        map<string, int> ans;

        stringstream ss;

        map<string, int> pre;
        int cnt = 0;
        while (i < s.size() && s[i] != ')') {
            if (s[i] >= 'A' && s[i] <= 'Z' || s[i] == '(') {
                fill(ans, ss, pre, cnt);
                ss.clear();
                ss.str("");
                pre.clear();
                cnt = 0;

                if (s[i] >= 'A' && s[i] <= 'Z') {
                    ss << s[i++];
                } else {
                    pre = f(s, i + 1, where);
                    i = where;
                }

            } else if (s[i] >= 'a' && s[i] <= 'z') {
                ss << s[i++];
            } else {
                cnt = cnt * 10 + s[i++] - '0';
            }
        }

        fill(ans, ss, pre, cnt);
        where = i + 1;
        return ans;
    }

    void fill(map<string, int>& ans, stringstream& ss, map<string, int>& pre,
              int cnt) {
        string str = ss.str();
        cnt = cnt == 0 ? 1 : cnt;
        if (!str.empty()) {
            ans[str] += cnt;
        }

        if (!pre.empty()) {
            for (pair<const string, int>& ky : pre) {
                ans[ky.first] += ky.second * cnt;
            }
        }
    }
};
```

N皇后问题
[测试链接](https://leetcode.cn/problems/n-queens-ii/)

```c++
class Solution {
public:
    int totalNQueens(int n) {
        int ans = 0;

        f(n, 1, ans);

        return ans;
    }

    void f(const int& n, int row, int& ans) {
        if (row == n + 1) {
            ans += 1;
            return;
        }
        for (int j = 1; j <= n; j++) {
            if (!isValid(row, j, n)) {
                continue;
            }

            Chessboard[row] |= (1 << (31 - j));
            f(n, row + 1, ans);
            Chessboard[row] = 0;
        }
    }
    bool isValid(int row, int column, const int& n) {
        if (Chessboard[row] != 0)
            return false;

        for (int i = 1; i <= n; i++) {
            if (i == row)
                continue;

            if ((Chessboard[i] >> (31 - column)) & 1)
                return false;
        }

        for (int i = row + 1, j = column + 1; i <= n && j <= n; i++, j++) {
            if ((Chessboard[i] >> (31 - j)) & 1)
                return false;
        }
        for (int i = row - 1, j = column - 1; i >= 1 && j >= 1; i--, j--) {
            if ((Chessboard[i] >> (31 - j)) & 1)
                return false;
        }

        for (int i = row + 1, j = column - 1; i <= n && j >= 1; i++, j--) {
            if ((Chessboard[i] >> (31 - j)) & 1)
                return false;
        }

        for (int i = row - 1, j = column + 1; i >= 1 && j <= n; i--, j++) {
            if ((Chessboard[i] >> (31 - j)) & 1)
                return false;
        }

        return true;
    }

private:
    int Chessboard[11] = {0};
};



class Solution {
public:
    int totalNQueens(int n) {
        int limits = (1 << n) - 1;
        return f(limits, 0, 0, 0);
    }

    int f(int limits, int col, int left, int right) {
        if(limits == col) return 1;

        int ban = col | left | right;
        int candidate = limits & (~ban);

        int ans = 0;
        while(candidate) {
            int place = candidate & (-candidate);
            candidate ^= place;
            ans += f(limits, col | place, (left | place) >> 1, (right | place) << 1);
        }

        return ans;
    }
};
```

