class Solution {
public:
    string decodeString(string s) {
        int where = 0;

        return f(s, 0, where);
    }

    string f(string& str, int i, int& where) {
        int cnt = 0;
        stringstream ss;
        string s;
        while (i < str.size() && str[i] != ']') {
            if(str[i] >= 'a' && str[i] <= 'z') {
                ss << str[i++];
            } else if(str[i] >= '0' && str[i] <= '9') {
                cnt = cnt * 10 + str[i++] - '0';
            } else {
                s = f(str, i + 1, where);
                stringstream temp;
                for(int i = 0; i < cnt; i++) {
                    temp << s;
                }

                ss << temp.str();

                cnt = 0;
                i = where;
            }
        }

        where = i + 1;
        return ss.str();
    }
};
