```c++
class Solution {
public:
    string countOfAtoms(string formula) {
        int where = 0;
        map<string, int> atoms_cnt = f(formula, 0, where);
        stringstream ss;
        for (pair<const string, int>& ky : atoms_cnt) {
            ss << ky.first;
            if (ky.second > 1) {
                ss << ky.second;
            }
        }

        return ss.str();
    }

    map<string, int> f(string& s, int i, int& where) {
        map<string, int> ans;

        stringstream ss;

        map<string, int> pre;
        int cnt = 0;
        while (i < s.size() && s[i] != ')') {
            if (s[i] >= 'A' && s[i] <= 'Z' || s[i] == '(') {
                fill(ans, ss, pre, cnt);
                ss.clear();
                ss.str("");
                pre.clear();
                cnt = 0;

                if (s[i] >= 'A' && s[i] <= 'Z') {
                    ss << s[i++];
                } else {
                    pre = f(s, i + 1, where);
                    i = where;
                }

            } else if (s[i] >= 'a' && s[i] <= 'z') {
                ss << s[i++];
            } else {
                cnt = cnt * 10 + s[i++] - '0';
            }
        }

        fill(ans, ss, pre, cnt);
        where = i + 1;
        return ans;
    }

    void fill(map<string, int>& ans, stringstream& ss, map<string, int>& pre,
              int cnt) {
        string str = ss.str();
        cnt = cnt == 0 ? 1 : cnt;
        if (!str.empty()) {
            ans[str] += cnt;
        }

        if (!pre.empty()) {
            for (pair<const string, int>& ky : pre) {
                ans[ky.first] += ky.second * cnt;
            }
        }
    }
};
