**荷兰国旗问题**

```c++
// 左边区域小于x，中间区域等于x，右边区域大于x

void swap(int* a, int* b) {
    if(*a == *b) return;

    *a = *a ^ *b;
    *b = *a ^ *b;
    *a = *a ^ *b;
}

void split_section(int* arr, int start, int end) {
    if(start == end) return;

    int val = arr[end];
    int l = start, r = end;
    int i = l;

    while(i <= r) {
        if(arr[i] < val) {
            swap(arr + l, arr + i);
            l++;
            i++;
        } else if(arr[i] > val) {
            swap(arr + i, arr + r);
            r--;
        } else {
            i++;
        }
    }
}
