        arr[i] = 'r';
        ans += f(arr, i + 1);
        arr[i] = 'e';
        ans += f(arr, i + 1);
        arr[i] = 'd';
        ans += f(arr, i + 1);

        return ans;
    }
}

bool is(vector<char>& arr, int l, int r) {
    while(l < r) {
        if(arr[l++] != arr[r--]) {
