Node* merge_list(Node* head_1, Node* head_2) {
    if(!head_1) return head_2;
    if(!head_2) return head_1;

    Node* head = nullptr;
    if(head_1->val < head_2->val) {
        head = head_1;
        head_1 = head_1->next;
    } else {
        head = head_2;
        head_2 = head_2->next;
    }

    Node* cur = head;

    while(head_1 && head_2) {
        if(head_1->val < head_2->val) {
            cur->next = head_1;
            head_1 = head_1->next;
        } else {
            cur->next = head_2;
            head_2 = head_2->next;
        }
        cur = cur->next;
    }

    if(head_1) {
        cur->next = head_1;
    }

    if(head_2) {
        cur->next = head_2;
    }

    return head;
}
