ListNode *detectCycle(ListNode *head) {
    if(!head) return head;

    ListNode* slow = head;
    ListNode* fast = slow;
    while(fast && fast->next) {
        slow = slow->next;
        fast = fast->next->next;

        if(slow == fast) break;
    }

    if(!fast || !fast->next) return nullptr;

    slow = head;
    while(slow != fast) {
        slow = slow->next;
        fast = fast->next;
    }

    return slow;
}
