    ListNode *pre = nullptr, *left = nullptr, *right = nullptr, *back = dummy;
    ListNode* temp = nullptr;
    for (int step = 1; step < len; step <<= 1) {
        back = dummy;
        while (back) {
            pre = back;

            left = pre->next;

            right = left;
            for (int i = 1; i < step && right; i++) {
                right = right->next;
            }

            if (right) {
                temp = right;
                right = temp->next;
                temp->next = nullptr;

                temp = right;
                for (int i = 1; i < step && temp; i++) {
                    temp = temp->next;
                }

                if (temp) {
                    back = temp->next;
                    temp->next = nullptr;
                } else {
                        back = temp;
                }
            } else {
                back = right;
            }

            pre->next = merge_sort(left, right);
            temp = pre->next;

            while (temp && temp->next) {
                temp = temp->next;
            }

            if(temp) {
                temp->next = back;
                back = temp;
            }
        }
    }

    temp = dummy->next;
    delete dummy;

    return temp;
}

```

