    cur = temp;

    while(next) {
        node = next->next;
        next->next = node->next;
        node->next = cur->next;
        cur->next = node;

         cur = cur->next;
        next = next->next;
    }

    Node* ans = temp->next;

    delete temp;
    return ans;
}
