判断链表是否是回文结构
[测试链接](https://leetcode.cn/problems/palindrome-linked-list/)

```c++
int get_len(ListNode* head) {
    int cnt = 0;
    while(head){
        cnt++;
        head = head->next;
    }
    return cnt;
}

ListNode* reverse_list(ListNode* head) {
    ListNode* dummy = new ListNode(-1, nullptr);
    ListNode* cur = dummy, * temp = nullptr;

    while(head) {
        temp = head->next;

        head->next = cur->next;
        cur->next = head;

        head = temp;
    }

    cur = dummy->next;
    delete dummy;

    return cur;
}

bool is_palindrome(ListNode* head) {
    ListNode* head_1 = nullptr, * head_2 = nullptr;
    bool flag = true;

    int len = get_len(head);
    if (len == 1)
        return flag;

    head_2 = head;
    for(int i = 0, n = len / 2; i < n; i++){
        head_2 = head_2->next;
    }

    if(len % 2) {
        head_1 = head_2->next;
        head_2 = head_1->next;
        head_1->next = nullptr;
    } else {
        head_1 = head_2;
        head_2 = head_1->next;
        head_1->next = nullptr;
    }

    head_1 = head;
    head_2 = reverse_list(head_2);

    ListNode* node = head_2;
    while(node) {
        if(node->val != head_1->val) {
            flag = false;
            break;
        }

        head_1 = head_1->next;
        node = node->next;
    }

    head_2 = reverse_list(head_2);
    head_1 = head;
    while(head_1->next){
        head_1 = head_1->next;
    }

    head_1->next = head_2;


    return flag;
}
```

返回链表的第一个入环节点
[测试链接](https://leetcode.cn/problems/linked-list-cycle-ii/)

```c++
ListNode *detectCycle(ListNode *head) {
    if(!head) return head;

    ListNode* slow = head;
    ListNode* fast = slow;
    while(fast && fast->next) {
        slow = slow->next;
        fast = fast->next->next;

        if(slow == fast) break;
    }

    if(!fast || !fast->next) return nullptr;

    slow = head;
    while(slow != fast) {
        slow = slow->next;
        fast = fast->next;
    }

    return slow;
}
```

排序链表
