        int size = 0;
        TreeNode* node = nullptr;

        while (l < r) {
            size = r - l;
            for (int i = 0; i < size; i++) {
                node = que[l++];

                if (node->left) {
                    que[r++] = node->left;
                    ss << node->left->val << ',';
                } else {
                    ss << "#,";
                }

                if (node->right) {
                    que[r++] = node->right;
                    ss << node->right->val << ',';
                } else {
                    ss << "#,";
                }
            }
        }

        return ss.str();
    }

    // Decodes your encoded data to tree.
    TreeNode* deserialize(string data) {
        if (data.empty())
            return nullptr;

        vector<string> leveOrder = split(data, ',');
        int i = 0;
        TreeNode* root = new TreeNode(stoi(leveOrder[i++]));
        TreeNode* node = nullptr;

        l = r = 0;
        que[r++] = root;

        while (l != r) {
            node = que[l++];

            if (leveOrder[i] == "#") {
                i++;
            } else {
                node->left = new TreeNode(stoi(leveOrder[i++]));
                que[r++] = node->left;
            }

            if (leveOrder[i] == "#") {
                i++;
            } else {
                node->right = new TreeNode(stoi(leveOrder[i++]));
                que[r++] = node->right;
            }
        }

        return root;
