class Solution {
public:
    bool isCompleteTree(TreeNode* root) {
        l = r = 0;
        que[r++] = root;

        TreeNode* node = nullptr;
        bool leaf = false;
        while(l < r) {
            node = que[l++];

            if((!node->left && node->right) || (leaf && (node->left || node->right))){
                return false;
            }

            if(node->left){
                que[r++] = node->left;
            }
            if(node->right) {
                que[r++] = node->right;
            }

            if(!node->left || !node->right){
