        if(!root) {
            yes = 0;
            no = 0;

            return;
        }

        int y = root->val, n = 0;

        f(root->left);
        y += no;
        n += max(yes, no);

        f(root->right);
        y += no;
        n += max(yes, no);

        yes = y;
        no = n;
    }

