## 常见数据结构设计

setAll功能的哈希表
[测试链接](https://www.nowcoder.com/practice/7c4559f138e74ceb9ba57d76fd169967)

```c++
#include <iostream>
#include <sstream>
#include <string>
#include <streambuf>
#include <vector>
#include <unordered_map>
using namespace std;

int timestamp = 0;
int setVal = 0;
int setTime = 0;

int main() {
    stringstream ss;
    ss << cin.rdbuf();

    int n;
    ss >> n;

    unordered_map<int, vector<int>> dict;

    int op = 0, k = 0, v = 0;
    for(int i = 0; i < n; i++) {
        ss >> op;
        if(op == 1) {
            ss >> k >> v;
            dict[k] = {v, timestamp++};
        }

        if(op == 2) {
            ss >> k;
            auto it = dict.find(k);
            if(it == dict.end()) {
                cout << -1 << endl;
                continue;
            }

            int time = it->second.back();
            cout << (time < setTime ? setVal : it->second.front()) << endl;
        }

        if(op == 3) {
            ss >> k;
            setVal = k;
            setTime = timestamp++;
        }
    }
}
```

