        while(max_heap.size() > (min_heap.size() + 1)) {
            min_heap.push(max_heap.top());
            max_heap.pop();
        }

        while(max_heap.size() < min_heap.size()) {
            max_heap.push(min_heap.top());
            min_heap.pop();
        }
    }

