```c++
class Solution {
public:
    int superpalindromesInRange(string left, string right) {
        long long l = stoll(left);
        long long r = stoll(right);

        long long limit = static_cast<long long>(sqrt(r));
        long long num = 0;
        long long val = 1;
        int cnt = 0;

        do {
            num = even(val);

            if (num <= limit && safeSquare(num) && check(num * num, l, r)) {
                cnt++;
            }

            num = odd(val);

            if (num <= limit && safeSquare(num) && check(num * num, l, r)) {
                cnt++;
            }

            val++;
        } while (num < limit);

        return cnt;
    }

   bool safeSquare(long long val) {
       return val <= static_cast<long long>(sqrt(numeric_limits<long long>::max()));
   }

    long long even(long long val) {
        long long ans = val;

        while (val != 0) {
            ans = ans * 10 + val % 10;
            val /= 10;
        }

        return ans;
    }

    long long odd(long long val) {
        long long ans = val;
        val /= 10;

        while (val != 0) {
            ans = ans * 10 + val % 10;
            val /= 10;
        }

        return ans;
    }

    bool check(long long val, long long l, long long r) {
        return val >= l && val <= r && is(val);
    }

    bool is(long long val) {
        long long offset = 1;
        while (val / offset >= 10) {
            offset *= 10;
        }

        while (val != 0) {
            if ((val / offset) != (val % 10)) {
                return false;
            }

            val = (val % offset) / 10;
            offset /= 100;
        }

        return true;
    }
};
```

