## 字典树

字典树（TrieTree），是一种树形结构，典型应用是用于统计，排序和保存大量的字符串（但不仅限于字符串,如01字典树）。主要思想是利用字符串的公共前缀来节约存储空间。

![](../../asset/blog_18_1.png)

```c++
#include <sstream>
#include <string>
#include <iostream>
#include <array>
using namespace std;

constexpr long long MAX = 10000005;
array<array<int, 26>, MAX> trie = {0};
array<int, MAX> pass = {0};
array<int, MAX> exist = {0};

int cnt = 0;


void insert(string word) {
    int p = 0;
    for (int i = 0, n = word.size(); i < n; i++) {
        int c = word[i] - 'a';
        if (!trie[p][c]) trie[p][c] = ++cnt;
        p = trie[p][c];

        pass[p]++;
    }
    exist[p]++;
}

int search(string word) {
    int p = 0;
    for (int i = 0, n = word.size(); i < n; i++) {
        int c = word[i] - 'a';
        if (!trie[p][c]) return false;

        p = trie[p][c];
    }

    return exist[p];
}

int prefix_number(string prefix) {
    int p = 0;
    for (int i = 0, n = prefix.size(); i < n; i++) {
        int c = prefix[i] - 'a';
        if (!trie[p][c]) return 0;

        p = trie[p][c];
    }

    return pass[p];
}

void delete_word(string word) {
    if (search(word) == 0) return;

    int p = 0;
    for (int i = 0, n = word.size(); i < n; i++) {
        int c = word[i] - 'a';

        p = trie[p][c];
        pass[p]--;
    }

    exist[p]--;
}

int main() {
    stringstream ss;
    ss << cin.rdbuf();

    int n = 0;
    ss >> n;

    int op = -1;
    string word = "";

    for(int i = 0; i < n; i++) {
        ss >> op >> word;
        switch(op) {
            case 1:
                insert(word);
                break;
            case 2:
                delete_word(word);
                break;

            case 3:
                cout << (search(word) > 0 ? "YES" : "NO") << endl;
                break;

            case 4:
                cout << prefix_number(word) << endl;
                break;
            default:
                break;
        }
    }

    return 0;
}
```

