```c++
class Solution {
public:
    int subarraySum(vector<int>& nums, int k) {
        unordered_map<int, int> mp;
        mp[0] = 1;

        int ans = 0;
        for (int i = 0, n = nums.size(), prefix_sum = 0; i < n; i++) {
            prefix_sum += nums[i];

            auto it = mp.find(prefix_sum - k);
            if (it != mp.end()) {
                ans += it->second;
            }

            mp[prefix_sum]++;
        }

        return ans;
    }
};
```

