#include<iostream>
#include<vector>
#include<limits>
#include<sstream>

int main() {
    std::stringstream ss;
    ss << std::cin.rdbuf();

    int n, m;
    ss >> n >> m;
    std::vector<long long> arr(n + 5);

    for(int i = 0; i < m; i++) {
        int l, r;
        ss >> l >> r;
        long long s, e, d;
        ss >> s >> e;
        d = (e - s) / (r - l);

        arr[l] += s;
        arr[l + 1] += d - s;
        arr[r + 1] -= d + e;
        arr[r + 2] += e;
    }

    for(int i = 1; i <= n; i++) {
        arr[i] += arr[i - 1];
    }
    for(int i = 1; i <= n; i++) {
        arr[i] += arr[i - 1];
    }

    long long xor_val = 0, max_val = std::numeric_limits<long long>::min();
    for(int i = 1; i <= n; i++) {
        xor_val ^= arr[i];
        max_val = std::max(max_val, arr[i]);
    }

    std::cout << xor_val << ' ' << max_val;
    return 0;
}
