class Solution {
public:
    int maxArea(vector<int>& height) {
        int l = 0, r = height.size() - 1;
        int ans = numeric_limits<int>::min();

        int h = 0, w = 0, area = 0;
        while (l < r) {
            h = min(height[l], height[r]);
            w = r - l;
            area = h * w;

            ans = max(ans, area);

            if (h == height[l]) {
                l++;
            } else {
                r--;
            }
        }

        return ans;
    }
};
