class Solution {
public:
    int smallestDistancePair(vector<int>& nums, int k) {
        sort(nums.begin(), nums.end());
        int l = 0, r = nums.back();
        long long cnt = 0, ans = 0;
        int m;
        while(l <= r) {
            m = l + (r - l) / 2;

            cnt = f(nums, m);
            if(cnt >= k) {
                ans = m;
                r = m - 1;
            } else {
                l = m + 1;
            }
        }

        return ans;
    }

    long long f(vector<int>& nums, int val) {
        long long ans = 0;
        for(int l = 0, r = 0; l < nums.size(); l++) {
            while(r + 1 < nums.size() && nums[r + 1] - nums[l] <= val) {
                r++;
            }

            ans += r - l;
        }

        return ans;
    }
};
