```c++
class Solution {
public:
    long long maxRunTime(int n, vector<int>& batteries) {
        long long l = 0, r = 0;
        long long sum = 0;

        for(int val : batteries) {
            r = max(r, (long long)val);
            sum += val;
        }

        if(sum >= (long long)n * r) {
            return sum / n;
        }

        long long m, ans = 0;

        while (l <= r) {
            m = l + (r - l) / 2;

            if (f(n, batteries, m)) {
                ans = m;
                l = m + 1;
            } else {
                r = m - 1;
            }
        }

        return ans;
    }

    bool f(int n, vector<int>& batteries, int limit) {
        long long sum = 0;
        for (int val : batteries) {
            if (val > limit) {
                n--;
            } else {
                sum += val;
            }

            if (sum >= ((long long)n * limit)) {
                return true;
            }
        }

        return false;
    }
};
```

